WITH transactions_by_account AS (SELECT account_id, ROUND((100 * SUM(CASE WHEN txn_type = 'FEE' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_fee, MAX(txn_time) AS last_txn_time FROM transactions GROUP BY account_id) SELECT a.id, a.customer_id, a.opened_date, tba.pct_fee, tba.last_txn_time FROM accounts a LEFT JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.pct_fee >= 42 ORDER BY opened_date;
